const tabId = 248688717;

const info = await browserjs(tabId, () => {
  const btn = document.querySelector('button[aria-label*="Location"], button[title*="Location"], [data-testid*="location"]');
  // let's find all buttons or elements with text containing Location
  const allElements = Array.from(document.querySelectorAll('button, a'));
