const tabId = 248688717;

const modalContent = await browserjs(tabId, () => {
  const modal = document.querySelector('.ups-location-modal-close')?.closest('.modal, [class*="modal"], [class*="flyout"], [class*="dialog"]') || document.querySelector('[id*="location"], [class*="location"]');
  // Or let's inspect the parent containers of ups-flyout-close-button
  const closeBtn = document.getElementById('ups-flyout-close-button');
  if (!closeBtn) return "No close button found";
  let parent = closeBtn.parentElement;
  while (parent && parent.tagName !== 'BODY') {
    if (parent.className.includes('modal') || parent.id.includes('modal') || parent.id.includes('flyout')) {
      return {
        id: parent.id,
        className: parent.className,
        innerHTML: parent.innerHTML.slice(0, 1500)
      };
    }
    parent = parent.parentElement;
  }
  return { parentHtml: closeBtn.parentElement.innerHTML.slice(0, 1500) };
});

console.log(modalContent);

