const modalBody = await browserjs(tabId, () => {
  const header = document.querySelector('.ups-location-modal-header');
  const container = header?.closest('.modal-content') || header?.parentElement;
  if (!container) return "No container found";

  // Find all inputs, buttons, selects, forms in container
  const inputs = Array.from(container.querySelectorAll('input, select, button, form, a')).map(el => ({
    tagName: el.tagName,
    id: el.id,
    className: el.className,
    type: el.type,
    placeholder: el.placeholder,
    value: el.value,
    text: el.textContent.trim(),
    name: el.name
  }));

  return {
    containerClass: container.className,
    containerText: container.innerText,
    inputs: inputs
  };
});

